/// Two dependent loads and no branching on data, replacing the range
/// binary searches this file used to emit.
pub fn record(cp: u21) Record {
    if (cp >= 0x110000) return record_default;
    const block = record_index[cp >> record_block_shift];
    const offset = (@as(usize, block) << record_block_shift) | (cp & (@as(usize, 1) << record_block_shift) - 1);
    return @bitCast(record_data[offset]);
}

pub fn graphemeOf(r: Record) GraphemeProperties {
    return @bitCast(@as(u7, @truncate(@as(u32, @bitCast(r)))));
}

pub fn graphemeProperties(cp: u21) GraphemeProperties { return graphemeOf(record(cp)); }

pub fn lineBreak(cp: u21) LineBreak { return record(cp).line_break; }
pub fn codepointWidth(cp: u21) u2 { return record(cp).width; }

pub fn isOp30(cp: u21) bool { return record(cp).lb_op30; }
pub fn isCp30(cp: u21) bool { return record(cp).lb_cp30; }
pub fn isQuPi(cp: u21) bool { return record(cp).lb_qu_pi; }
pub fn isQuPf(cp: u21) bool { return record(cp).lb_qu_pf; }
pub fn isBaHyphen(cp: u21) bool { return record(cp).lb_ba_hyphen; }
pub fn isSaMnMc(cp: u21) bool { return record(cp).lb_sa_mn_mc; }
pub fn isEastAsianWide(cp: u21) bool { return record(cp).east_asian_wide; }
pub fn isExtendedPictographicCn(cp: u21) bool { return record(cp).ep_cn; }
